def f(di):
    H,W=len(di),len(di[0])
    # find blocks: maximal vertical color segments
    def blocks(g):
        bs=[]; cur=None
        for r in range(H):
            for c in range(W):
                v=g[r][c]
                if v==0: continue
                if cur is None or (r,cur[0])!=(r-1,cur[0]) or g[r][c]!=cur[2]:
                    if cur: bs.append((cur[0],cur[1],cur[2],cur[3]))
                    cur=(r,c,v,0)
                else:
                    cur=(cur[0],cur[1],v,cur[3]+1)
            if cur is not None and g[H-1][W-1]!=cur[2] or r==H-1:
                if cur: bs.append((cur[0],cur[1],cur[2],cur[3]+1))
        return bs
    bs=blocks(di)
    # base = block with most cells
    base=max(bs,key=lambda b:sum(1 for r in range(b[0]-b[0]) for c in range(W) if di[r][c]==b[2])) if False else None
    # simpler: count cells per color block
    best=None; bestn=-1
    for s,e,col,_ in bs:
        n=sum(1 for r in range(s,e) for c in range(W) if di[r][c]==col)
        if n>bestn: bestn,n_=best,n=s,e,col
        bestn=n; best=(s,e,col)
    s,e,basecol=best
    base=[[di[s+i][j] for j in range(W)] for i in range(e-s)]
    Hb=e-s
    out=[[base[i][j] if base[i][j] else None for j in range(W)] for i in range(Hb)]
    # painters: other blocks with at least one horizontal run
    for s2,e2,col,_ in bs:
        if (s2,e2,col)==(s,e,basecol): continue
        has_run=any(di[r][c]==col and (c>0 and di[r][c-1]==col) or (c<W-1 and di[r][c+1]==col) for r in range(s2,e2) for c in range(W))
